arguments.content:
data {
  int<lower=1> N;
  array[N] int<lower=0> y;
  array[N] int<lower=0> n;
}

parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}

model {
  // Hyperprior p(alpha, beta) is proportional to (alpha + beta)^(-5/2).
  target += -2.5 * log(alpha + beta);

  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}

arguments.command:
set -eu
Rscript - <<'RS'
options(repos = c(CRAN = "https://cloud.r-project.org"), Ncpus = 8L, timeout = 1200)
if (!requireNamespace("remotes", quietly = TRUE)) {
  install.packages("remotes")
}
if (!requireNamespace("rstan", quietly = TRUE) || packageVersion("rstan") != "2.32.7") {
  remotes::install_version(
    "rstan",
    version = "2.32.7",
    repos = "https://cloud.r-project.org",
    dependencies = c("Depends", "Imports", "LinkingTo"),
    upgrade = "never",
    INSTALL_opts = "--no-multiarch"
  )
}
if (!requireNamespace("rstan", quietly = TRUE)) stop("rstan installation failed")
cat("Installed rstan version:", as.character(packageVersion("rstan")), "\n")
if (packageVersion("rstan") != "2.32.7") stop("Required rstan version 2.32.7 was not installed")
RS

